using Microsoft.AspNetCore.Localization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Localization;
using OnlineAuction.Localization;

namespace OnlineAuction.Controllers;

public class TestController : Controller
{
    private readonly IStringLocalizer<SharedResource> _localizer;

    public TestController(IStringLocalizer<SharedResource> localizer)
    {
        _localizer = localizer;
    }

    public IActionResult Index()
    {
        var culture = HttpContext.Features.Get<IRequestCultureFeature>()?.RequestCulture.Culture.Name ?? "N/A";
        var homeText = _localizer["Home"];
        var auctionText = _localizer["Auction"];

        ViewBag.Culture = culture;
        ViewBag.HomeText = homeText;
        ViewBag.AuctionText = auctionText;
        ViewBag.AllCookies = HttpContext.Request.Headers.Cookie.ToString();

        return View();
    }
}
